const titles={dashboard:['OVERVIEW','Your financial picture, made clearer.'],planning:['PLAN & BUILD','Build a plan that fits your life.'],borrowing:['LOAN WORKSPACE','Understand your debt. Choose your next move.'],workspace:['DATA & SETTINGS','Your financial data, your choice.'],loanDashboard:['LOAN OVERVIEW','Your repayment plan, made clearer.'],family:['FAMILY WEALTH','Your household financial picture.'],loans:['PORTFOLIO','Manage your loans.'],prepayments:['PAYMENT PLANS','Make extra payments count.'],bonus:['WINDFALL PLANNER','Give every bonus a job.'],advisor:['SMART ALLOCATION','Compare where extra money goes.'],scenarios:['WHAT-IF PLANNING','Test a plan before committing.'],schedule:['AMORTIZATION','See every repayment period.'],reports:['ANALYTICS','Understand the full repayment picture.'],networth:['WEALTH PLANNING','See where your whole financial picture could go.'],cashflow:['CASH FLOW','Balance income, commitments, and surplus.'],goals:['YOUR GOALS','Make progress towards what matters.'],emergencyFund:['SAFETY NET','Build a liquid emergency reserve.'],calendar:['UPCOMING CASH FLOW','See planned cash flow by month.'],whatif:['WHAT-IF PLANNING','Explore possibilities without changing your plan.'],reviews:['ACCOUNT HEALTH','Keep your financial balances up to date.'],data:['PORTABILITY','Your data, under your control.'],settings:['PREFERENCES','Set the rules for your workspace.']};
function render(){
 const t=titles[page]||titles.dashboard;
 $('#crumb').textContent=t[0];
 $('#pageTitle').textContent=t[1];
 $('#content').innerHTML=groupNavigation(page)+(renderers[page]||dashboard)();
 const switcher=$('#portfolioSwitcher');
 if(switcher){
  switcher.innerHTML=workspace.portfolios.map(p=>`<option value="${escapeHTML(p.id)}" ${p.id===workspace.activePortfolioId?'selected':''}>${escapeHTML(p.name)}${p.archived?' (archived)':''}</option>`).join('');
  switcher.disabled=!!pendingImportPortfolioId||!$('#modalBackdrop').classList.contains('hidden');
 }
 updateResumeDraft();
 window.refreshAppControls?.();
 const activeSection=page==='dashboard'||page==='family'?page:pageGroup(page);
 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===activeSection));
 if(page==='loanDashboard')drawBalanceChart();
 if(page==='dashboard'||page==='networth')drawNetworthChart();
 if(page==='whatif')drawWhatIfChart();
 if(page==='schedule'){
  const el=$('#scheduleLoan');
  if(el)el.addEventListener('change',()=>{activeSchedule=el.value;render()});
  const period=$('#schedulePeriod');
  if(period)period.addEventListener('change',()=>{
   const l=state.loans.find(x=>x.id===activeSchedule),sc=LoanCalc.simulateLoan(l,{prepayments:state.prepayments});
   let rows=sc.rows;
   if(period.value==='quarter')rows=LoanCalc.scheduleSummary(rows,'quarter');
   if(period.value==='year')rows=LoanCalc.scheduleSummary(rows,'year');
   if(period.value==='fy'){
    const grouped=new Map();
    rows.forEach(r=>{
     const key=LoanReports.financialYear(r.date);
     if(!grouped.has(key))grouped.set(key,{period:'FY '+key,principal:0,interest:0,prepayment:0,fees:0,cash:0,scheduledClosing:0,closing:0});
     const item=grouped.get(key);
     ['principal','interest','prepayment','fees','cash'].forEach(k=>item[k]+=r[k]);
     item.scheduledClosing=r.scheduledClosing??r.closing;
     item.closing=r.closing;
    });
    rows=[...grouped.values()];
   }
   $('#scheduleTable').innerHTML=scheduleTable(rows.map(r=>({...r,opening:r.opening??0,emi:r.emi??r.cash})));
  });
 }
}
function drawBalanceChart(){const c=$('#balanceChart');if(!c)return;const ctx=c.getContext('2d'),data=activeLoans().slice(0,7);const w=c.clientWidth||500,h=c.clientHeight||230,dpr=window.devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body),muted=css.getPropertyValue('--muted'),line=css.getPropertyValue('--line'),green=css.getPropertyValue('--green');const max=Math.max(1,...data.map(x=>+x.principal));const left=10,right=12,top=12,bottom=35,chartH=h-top-bottom;ctx.font='10px DM Sans, sans-serif';data.forEach((l,i)=>{let slot=(w-left-right)/Math.max(1,data.length),barW=Math.min(36,slot*.48),x=left+slot*i+(slot-barW)/2,bh=chartH*(l.principal/max);ctx.fillStyle=green;ctx.beginPath();let y=top+chartH-bh;ctx.roundRect(x,y,barW,bh,4);ctx.fill();ctx.fillStyle=muted;ctx.textAlign='center';let name=l.name.length>10?l.name.slice(0,9)+'…':l.name;ctx.fillText(name,x+barW/2,h-14);});ctx.strokeStyle=line;ctx.beginPath();ctx.moveTo(left,h-bottom+1);ctx.lineTo(w-right,h-bottom+1);ctx.stroke()}
