$('#menuToggle').onclick=()=>{const shell=$('.app-shell');const mobile=window.matchMedia('(max-width:720px)').matches;const collapsed=!mobile&&!shell.classList.contains('sidebar-collapsed'),open=mobile?!shell.classList.contains('mobile-nav-open'):!collapsed;shell.classList.toggle(mobile?'mobile-nav-open':'sidebar-collapsed',mobile?open:collapsed);syncMenuToggle()};syncMenuToggle();$('#resumeDraft').onclick=()=>{const draft=readLoanDraft();if(draft?.values)openModal(draft.title||(draft.editingId?'Edit loan':'Add loan'),draft.editingId,true)};$('#modalClose').onclick=()=>closeModal();$('#cancelLoan').onclick=()=>closeModal(true);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});$('#loanForm').addEventListener('submit',saveLoanForm);$('#loanForm').addEventListener('input',saveLoanDraft);$('#loanForm').addEventListener('change',saveLoanDraft);
$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');$('#themeBtn').textContent=document.body.classList.contains('dark')?'☼ Light':'◐ Theme';if(page==='loanDashboard')drawBalanceChart();if(page==='dashboard'||page==='networth')drawNetworthChart();if(page==='whatif')drawWhatIfChart()};
$('#fileInput').addEventListener('change',e=>{let file=e.target.files[0];if(file)importFile(file,e.target.dataset.kind);else{pendingImportPortfolioId=null;$('#portfolioSwitcher').disabled=false}e.target.value=''});
function updateWhatIf(){
 whatIf.savingsRate=Number($('#whatIfSavings').value);whatIf.returnDelta=Number($('#whatIfReturn').value);whatIf.incomeGrowthDelta=Number($('#whatIfIncome').value);whatIf.monthlyLoanExtra=Number($('#whatIfExtra').value)||0;whatIf.loanId=$('#whatIfLoan').value;
 $('#whatIfSavingsLabel').textContent=`${whatIf.savingsRate}%`;$('#whatIfReturnLabel').textContent=`${whatIf.returnDelta}%`;$('#whatIfIncomeLabel').textContent=`${whatIf.incomeGrowthDelta}%`;
 const horizon=state.networth.assumptions.projectionYears,{baseline,scenario}=whatIfProjections();$('#whatIfResults').innerHTML=whatIfResultsMarkup(baseline[horizon],scenario[horizon],horizon);drawWhatIfChart();
}
$('#content').addEventListener('input',e=>{
 if(page==='networth'&&e.target.id==='projectionYears'){state.networth.assumptions.projectionYears=Number(e.target.value);$('#projectionYearsLabel').textContent=`${e.target.value} years`;$('#networthProjection').innerHTML=networthProjectionMarkup();drawNetworthChart()}
 if(page==='whatif'&&['whatIfSavings','whatIfReturn','whatIfIncome','whatIfExtra'].includes(e.target.id))updateWhatIf();
});
$('#content').addEventListener('change',e=>{
 if(e.target.id==='importMode')importMode=e.target.value;
 if(page==='emergencyFund'&&e.target.id==='emergencyFundMonths'){
  state.planning.assumptions.emergencyFundMonths=Math.max(1,Math.min(24,Math.floor(Number(e.target.value)||6)));saveDirty();render();return;
 }
 if(page==='whatif'&&e.target.id==='whatIfLoan'){updateWhatIf();return}
 if(page==='goals'&&e.target.dataset.goalAssetField){
  const goal=state.planning.goals.find(x=>x.id===e.target.dataset.goalId),plan=goal?.assetPlans.find(x=>x.assetId===e.target.dataset.assetPlanId),field=e.target.dataset.goalAssetField;
  if(goal&&plan){
   if(field==='assetId'){
    const asset=state.networth.assets.find(x=>x.id===e.target.value);
    const assignedElsewhere=state.planning.goals.some(item=>item!==goal&&(item.assetPlans||[]).some(x=>x.assetId===asset?.id));
    if(asset&&!assignedElsewhere&&!goal.assetPlans.some(x=>x!==plan&&x.assetId===asset.id)){plan.assetId=asset.id;plan.annualGrowth=asset.annualGrowth}
   }else{
    const value=Number(e.target.value);
    if(Number.isFinite(value))plan[field]=field==='annualGrowth'?Math.max(-100,Math.min(100,value)):Math.max(0,value);
   }
   saveDirty();render();
  }
  return;
 }
 if(page==='networth'&&e.target.dataset.networthField){
  const item=state.networth[e.target.dataset.group].find(x=>x.id===e.target.dataset.id),field=e.target.dataset.networthField;
  if(item){if(field==='name')item.name=e.target.value.trim()||'Untitled';else if(field==='emergencyEligible')item[field]=e.target.checked;else{const value=Number(e.target.value);item[field]=Number.isFinite(value)?Math.max(field==='annualGrowth'?-100:0,field==='annualGrowth'?Math.min(100,value):value):0}}
  saveDirty();render();
 }else if(page==='networth'&&e.target.dataset.networthAssumption){
  const field=e.target.dataset.networthAssumption,value=Number(e.target.value);
  state.networth.assumptions[field]=Number.isFinite(value)?Math.max(0,Math.min(field==='inflationRate'?30:100,value)):0;
  saveDirty();render();
 }else if(page==='networth'&&e.target.id==='projectionYears')saveDirty();
 else if(['cashflow','goals','networth'].includes(page)&&e.target.dataset.planningField){
  const group=e.target.dataset.group,item=state.planning[group].find(x=>x.id===e.target.dataset.id),field=e.target.dataset.planningField;
  if(item){
   if(field==='essential')item[field]=e.target.checked;
   else if(['name','type','targetDate'].includes(field))item[field]=field==='name'?(e.target.value.trim()||'Untitled'):e.target.value;
   else{const value=Number(e.target.value);const max=['annualRate'].includes(field)?100:field==='annualGrowth'?100:Number.MAX_VALUE;item[field]=Number.isFinite(value)?Math.max(field==='annualGrowth'?-100:0,Math.min(max,value)):0}
  }
  saveDirty();render();
 }else if(page==='reviews'&&e.target.dataset.reviewGroup){
  const {reviewGroup:group,id}=e.target.dataset,item=(group==='assets'?state.networth.assets:group==='liabilities'?state.planning.liabilities:state.loans).find(x=>x.id===id);
  if(item){if(e.target.classList.contains('review-date'))item.reviewedAt=e.target.value;else item.reviewIntervalMonths=Math.max(1,Math.min(60,Number(e.target.value)||12));saveDirty();render()}
 }
});
